        set.add("Java");  
        set.add("T");  
        set.add("Point");  
        set.add("Good");  
        set.add("Website");  

        System.out.println("The hash set is: " + set);  

        System.out.println(set.remove("Good"));  

        System.out.println("After removing the element, the hash set is: " + set);  

        System.out.println(set.remove("For"));  
    }  
